import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.Dnb1kVW5.js";const m=JSON.parse('{"title":"LLM models","description":"","frontmatter":{"title":"LLM models"},"headers":[],"relativePath":"docs/concepts/llm-models.md","filePath":"docs/concepts/llm-models.md","lastUpdated":1789172339000}'),r={name:"docs/concepts/llm-models.md"};function n(l,e,d,i,c,u){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="llm-models" tabindex="-1">LLM models <a class="header-anchor" href="#llm-models" aria-label="Permalink to &quot;LLM models&quot;">​</a></h1><p>Models are what power chat and question-answering in Orby. Orby distinguishes <strong>builtin</strong> models from <strong>configured</strong> models — the choice of which to use is yours, and can be changed at any time in <a href="/orby-releases/docs/settings/models">Settings → Models</a>.</p><h2 id="builtin-models" tabindex="-1">Builtin models <a class="header-anchor" href="#builtin-models" aria-label="Permalink to &quot;Builtin models&quot;">​</a></h2><p>Builtin models are run by Orby itself, entirely on your own machine. Because Orby controls them directly, they&#39;re always local and always trusted — nothing more to decide.</p><h2 id="configured-models" tabindex="-1">Configured models <a class="header-anchor" href="#configured-models" aria-label="Permalink to &quot;Configured models&quot;">​</a></h2><p>You can also configure additional models of your own — a different local model, a cloud API, or a subscription like Codex. Whether a configured model is trusted or untrusted is up to you, and depends on where it&#39;s actually running, who&#39;s running it, and how much you trust that setup. For example, you might configure a Codex subscription as an untrusted model.</p><h2 id="trusted-vs-untrusted" tabindex="-1">Trusted vs. untrusted <a class="header-anchor" href="#trusted-vs-untrusted" aria-label="Permalink to &quot;Trusted vs. untrusted&quot;">​</a></h2><p>Only a <strong>trusted</strong> model is given access to your actual project data. An <strong>untrusted</strong> model can still be useful for other tasks, but is never given access to your data. See <a href="/orby-releases/docs/concepts/privacy">Privacy</a> for how this fits into Orby&#39;s overall approach to your data.</p><h2 id="choosing-and-testing-a-model" tabindex="-1">Choosing and testing a model <a class="header-anchor" href="#choosing-and-testing-a-model" aria-label="Permalink to &quot;Choosing and testing a model&quot;">​</a></h2><p>See <a href="/orby-releases/docs/settings/models">Models</a> for how to configure one, and <a href="/orby-releases/docs/tools/model-test">Model Test</a> / <a href="/orby-releases/docs/tools/model-benchmark">Model Benchmark</a> for checking that a model works well before relying on it.</p>',10)])])}const f=o(r,[["render",n]]);export{m as __pageData,f as default};
